import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { LeishmaniaSpeciesComponent } from './leishmania-species.component';

const routes: Routes = [
  {
    path: '',
    component: LeishmaniaSpeciesComponent,
    data: {
      title: 'leishmania-species'
    }
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class leishmaniaSpeciesRoutingModule {}