import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { CookieService } from 'ngx-cookie';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';
import { leishmania_species} from '../model/leishmania_species'


@Injectable({
  providedIn: 'root'
})
export class LeishmaniaSpeciesService {

  constructor(private http: HttpClient ,private cookie : CookieService) { }

  private baseurl = environment.baseurl;

  public get_all_species(): Observable<any> {
    return this.http.get(this.baseurl + "leishmania_species/all",{observe: 'response'});
  }

  public delete_species(name: string): Observable<string> {
    return this.http.delete(this.baseurl + "leishmania_species/?id="+ name, { responseType: 'text' });
  }

  public add_species(leishmania_species :leishmania_species): Observable<string> {
    return this.http.post(this.baseurl + "leishmania_species/save", leishmania_species, { responseType: 'text'});
  }

  public update_species(leishmania_species:leishmania_species): Observable<string> {
    return this.http.post(this.baseurl + "leishmania_species/update", leishmania_species, { responseType: 'text' });
  }
  
  clear()
  {
    this.cookie.remove('token');
  }



}
